CREATE TABLE IF NOT EXISTS evidence(id TEXT PRIMARY KEY,url TEXT NOT NULL,title TEXT,subject TEXT,published_at TEXT,accessed_at TEXT NOT NULL,file_path TEXT NOT NULL,sha256 TEXT NOT NULL,status TEXT NOT NULL,method TEXT);
CREATE TABLE IF NOT EXISTS works(id TEXT PRIMARY KEY,title TEXT NOT NULL,aliases TEXT,author TEXT,platform TEXT NOT NULL,source_id TEXT,source_url TEXT,category_raw TEXT,category_mapped TEXT,serial_status TEXT,published_at TEXT,published_precision TEXT,completed_at TEXT,signing_raw TEXT,signing_evidence TEXT REFERENCES evidence(id),inclusion_status TEXT NOT NULL,inclusion_basis TEXT,identity_evidence TEXT REFERENCES evidence(id),first_seen TEXT,last_seen TEXT,sample INTEGER DEFAULT 0,stratum TEXT, UNIQUE(platform,source_id));
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY,parent_id TEXT REFERENCES products(id),title TEXT NOT NULL,media TEXT NOT NULL,season TEXT,language TEXT,markets TEXT,platform TEXT,source_id TEXT,source_url TEXT,producer TEXT,distributor TEXT,pay_model TEXT,status TEXT,confirmation TEXT,evidence_id TEXT REFERENCES evidence(id));
CREATE TABLE IF NOT EXISTS product_works(product_id TEXT REFERENCES products(id),work_id TEXT REFERENCES works(id),evidence_id TEXT REFERENCES evidence(id),PRIMARY KEY(product_id,work_id));
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY,work_id TEXT REFERENCES works(id),product_id TEXT REFERENCES products(id),event_type TEXT,event_time TEXT,time_end TEXT,time_precision TEXT,description TEXT,window_role TEXT,confirmation TEXT,evidence_id TEXT REFERENCES evidence(id));
CREATE TABLE IF NOT EXISTS observations(id TEXT PRIMARY KEY,work_id TEXT REFERENCES works(id),product_id TEXT REFERENCES products(id),metric_raw TEXT,metric_standard TEXT,raw_value TEXT,value REAL,lower_bound REAL,upper_bound REAL,unit TEXT,currency TEXT,temporal_type TEXT,observed_at TEXT,period_start TEXT,period_end TEXT,precision TEXT,missing_reason TEXT,comparison_version TEXT,evidence_id TEXT REFERENCES evidence(id));
CREATE TABLE IF NOT EXISTS coverage(id TEXT PRIMARY KEY,task_type TEXT NOT NULL,work_id TEXT REFERENCES works(id),media TEXT,partition TEXT,query_scope TEXT,cursor TEXT,status TEXT NOT NULL,displayed_total TEXT,discovered INTEGER,new_unique INTEGER,first_id TEXT,last_id TEXT,evidence_id TEXT REFERENCES evidence(id),gap TEXT,last_run TEXT);
CREATE TABLE IF NOT EXISTS check_history(id TEXT PRIMARY KEY,work_id TEXT REFERENCES works(id),media TEXT,status TEXT,query_scope TEXT,evidence_id TEXT REFERENCES evidence(id),checked_at TEXT,gap TEXT);
CREATE TABLE IF NOT EXISTS source_matrix(id TEXT PRIMARY KEY,media TEXT,source_name TEXT,url TEXT,events_available TEXT,current_values TEXT,historical_values TEXT,access_condition TEXT,test_result TEXT,evidence_id TEXT REFERENCES evidence(id),next_action TEXT);
CREATE TABLE IF NOT EXISTS exclusions(id TEXT PRIMARY KEY,source_url TEXT,title TEXT,reason TEXT,evidence_id TEXT REFERENCES evidence(id));
CREATE INDEX IF NOT EXISTS cov_work_media ON coverage(work_id,media);
